import functools

def log_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print('call', func.__name__, args, kwargs)
        result = func(*args, **kwargs)
        print('done', func.__name__, '->', result)
        return result
    return wrapper

@log_calls
def area(w, h=1):
    return w * h

area(3, h=4)
# call area (3,) {'h': 4}
# done area -> 12

import functools

def plain(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def kept(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@plain
def total(xs):
    """Sum xs."""
    return sum(xs)

@kept
def mean(xs):
    """Average of xs."""
    return sum(xs) / len(xs)

print(total.__name__, total.__doc__)  # wrapper None
print(mean.__name__, mean.__doc__)    # mean Average of xs.
print(mean.__wrapped__([2, 4]))       # 3.0, the original

