import functools

def count_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

def memo(func):
    seen = {}
    @functools.wraps(func)
    def wrapper(n):
        if n not in seen:
            seen[n] = func(n)
        return seen[n]
    return wrapper

@count_calls
def square(n):
    return n * n

@memo
def double(n):
    print('computing', n)
    return 2 * n

square(2); square(3)
print(square.calls)        # 2
double(5); double(5)       # prints 'computing 5' once

REGISTRY = {}

def register(cls):          # class decorator
    REGISTRY[cls.__name__] = cls
    return cls

@register
class Square:
    def __init__(self, side):
        self.side = side

    @property               # area = property(area)
    def area(self):
        return self.side ** 2

    @classmethod            # unit = classmethod(unit)
    def unit(cls):
        return cls(1)

    @staticmethod           # kind = staticmethod(kind)
    def kind():
        return 'polygon'

print(list(REGISTRY), Square.unit().area, Square.kind())
# ['Square'] 1 polygon

