import functools

def retry(times, on=ValueError):
    def decorate(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except on:
                    if attempt == times:
                        raise
        return wrapper
    return decorate

answers = iter([ValueError('busy'), ValueError('busy'), 'ok'])

@retry(3)
def fetch():
    item = next(answers)
    if isinstance(item, Exception):
        raise item
    return item

print(fetch(), fetch.__name__)   # ok fetch

