import functools

def retry(times, on=ValueError):
    def decorate(func):
        def wrapper(*args, **kwargs):
            # TODO: try up to `times` times, retrying only on `on`;
            # re-raise the last error. Keep func's metadata.
            return func(*args, **kwargs)
        return wrapper
    return decorate

# The driver is done: it builds a flaky fetch and reports what happened.
def run_with_retry(outcomes, times):
    remaining = iter(outcomes)
    calls = 0

    @retry(times)
    def fetch():
        nonlocal calls
        calls += 1
        outcome = next(remaining, 'fail')
        if outcome == 'fail':
            raise ValueError('transient')
        if outcome == 'crash':
            raise KeyError('fatal')
        return outcome

    try:
        result = fetch()
    except ValueError:
        result = 'gave up'
    except KeyError:
        result = 'crashed'
    return {'name': fetch.__name__, 'calls': calls, 'result': result}

solution:
def retry(times, on=ValueError):
    def decorate(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except on:
                    if attempt == times:
                        raise
        return wrapper
    return decorate

Three levels: `retry(times)` captures the options, `decorate(func)` captures the function, `wrapper` runs per call. Returning inside the `try` ends the loop on the first success, so a falsy result such as 0 or None is still returned correctly. `except on:` catches only the listed type, so a KeyError escapes on the first attempt. The bare `raise` on the final attempt re-raises the original exception with its traceback instead of hiding it. `functools.wraps` keeps the name, docstring and `__wrapped__`. At most `times` calls; no extra state lives between calls.

