import functools
from collections import deque

def rate_limit(limit, window, clock):
    def decorate(func):
        recent = deque()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = clock()
            while recent and recent[0] <= now - window:
                recent.popleft()
            if len(recent) >= limit:
                return 'blocked'
            recent.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorate

def rate_limited(requests, limit, window):
    now = 0

    def clock():
        return now

    @rate_limit(limit, window, clock)
    def handle(payload):
        return payload

    out = []
    for at, payload in requests:
        now = at
        out.append(handle(payload))
    return out

